import{_ as s,a0 as i,w as l,s as u,ao as o,I as r,x as t,a1 as n,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"Camicri Cube: 可離線的便攜包管理系統 | LCTT x X-CMD","titleTemplate":false,"description":"Camicri Cube: 可離線的便攜包管理系統 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Camicri Cube: 可離線的便攜包管理系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Camicri Cube: 可離線的便攜包管理系統 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140724 Camicri Cube--An Offline And Portable Package Management System","title":"Camicri Cube: 可離線的便攜包管理系統","tag":"201410","desc":""},"relativePath":"201410/20140724 Camicri Cube--An Offline And Portable Package Management System.md","filePath":"[post].md"}'),c={name:"201410/20140724 Camicri Cube--An Offline And Portable Package Management System.md"};function g(d,e,b,m,C,h){const a=i("Link");return l(),u("div",null,[e[18]||(e[18]=o('<h1 id="camicri-cube-可離線的便攜包管理系統" tabindex="-1">Camicri Cube: 可離線的便攜包管理系統 <a class="header-anchor" href="#camicri-cube-可離線的便攜包管理系統" aria-label="Permalink to “Camicri Cube: 可離線的便攜包管理系統”">​</a></h1><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/camicri-cube-206x205.jpg" alt=""></p><p>眾所周知，在系統中使用新立得包管理工具或軟件中心下載和安裝應用程序的時候，我們必須得有互聯網連接。但，如果您剛好沒有網絡或者是網絡速度死慢死慢的呢？在您的 Linux 桌面系統中使用軟件中心包管理工具來安裝軟件絕對是一個頭痛的問題。反而，您可以從相應的官網上手工下載應用程序包並手工安裝。但是，大多數的 Linux 用户並不知道他們希望安裝的應用程序所需要的依賴關係包。如果您恰巧出現這種情況，應用怎麼辦呢？現在一切都不用擔心了。今天，我們給您介紹一款非常棒的名叫 <strong>Camicri Cube</strong> 的離線包管理工具。</p><p>您可以把此包管理工具裝在任何聯網的系統上，下載您所需要安裝的軟件列表，然後把它們安裝到沒聯網的機器上，就可以安裝了。聽起來很不錯吧？是的，它就是這樣操作的。Cube 是一款像新立得和 Ubuntu 軟件中心這樣的包管理工具，但是一款便攜式的。它在任何平台（Windows 系統、基於 Apt 的 Linux 發佈系統）、在線狀態、離線狀態、在閃存或任何可移動設備上都是可以使用和運行的。我們這個實驗項目的主要目的是使處在離線狀態的 Linux 用户能很容易的下載和安裝 Linux 應用程序。</p><p>Cube 會收集您的離線電腦的詳細信息，如操作系統的詳細信息、安裝的應用程序等等。然後使用 USB 迷你盤對 cube 應用程序進行拷貝，得到一副本，把其放在其它有網絡連接的系統上使用，接着就可以下載您需要的應用程序列表。下載完所有需要的軟件包之後，回到您原來的計算機，並開始安裝。Cube 是由 <strong>Jake Capangpangan</strong> 開發和維護的，是用 C++ 語言編寫，而且已經集成了所有必須的包。因此，使用它並不需要再安裝任何額外的軟件。</p><h3 id="安裝" tabindex="-1">安裝 <a class="header-anchor" href="#安裝" aria-label="Permalink to “安裝”">​</a></h3>',6)),r("p",null,[e[2]||(e[2]=t("現在，讓我們下載 Cube 程序包，然後在沒有網絡連接的離線系統上進行安裝。既可以從",-1)),n(a,{href:"https://launchpad.net/camicricube"},{default:p(()=>[...e[0]||(e[0]=[t("官網主站頁面",-1)])]),_:1}),e[3]||(e[3]=t("下載，也可以從 ",-1)),n(a,{href:"http://sourceforge.net/projects/camicricube/"},{default:p(()=>[...e[1]||(e[1]=[t("Sourceforge 網站",-1)])]),_:1}),e[4]||(e[4]=t("下載。要確保下載的版本跟您的離線計算機架構對應的系統相匹配。比如我使用的是64位的系統，就要下載64位版本的安裝包。",-1))]),e[19]||(e[19]=o(`<pre><code>wget http://sourceforge.net/projects/camicricube/files/Camicri%20Cube%201.0.9/cube-1.0.9.2_64bit.zip/
</code></pre><p>對此 zip 文件解壓，解壓到 home 目錄或者着是您想放的任何地方：</p><pre><code>unzip cube-1.0.9.2_64bit.zip
</code></pre><p>這就好了。接着，該是知道怎麼使用的時候了。</p><h3 id="使用" tabindex="-1">使用 <a class="header-anchor" href="#使用" aria-label="Permalink to “使用”">​</a></h3><p>這兒，我使用的是兩台裝有 Ubuntu 系統的機器。原機器（離線-沒有網絡連接）上面跑着的是 <strong>Ubuntu 14.04</strong> 系統，有網絡連接的機器跑着的是 <strong>Lubuntu 14.04</strong> 桌面系統。</p><h4 id="離線系統上的操作步驟" tabindex="-1">離線系統上的操作步驟: <a class="header-anchor" href="#離線系統上的操作步驟" aria-label="Permalink to “離線系統上的操作步驟:”">​</a></h4><p>在離線系統上，進入已經解壓的 Cube 文件目錄，您會發現一個名叫 “cube-linux” 的可執行文件，雙擊它，並點擊執行。如果它是不可執行的，用如下命令設置其可執行權限。</p><pre><code>sudo chmod -R +x cube/
</code></pre><p>然後，進入 cube 目錄，</p><pre><code>cd cube/
</code></pre><p>接着執行如下命令來運行：</p><pre><code>./cube-linux
</code></pre><p>輸入項目的名稱（比如sk）然後點擊<strong>創建</strong>按紐。正如我上面提到的，這將會創建一個與您的系統相關的完整詳細信息的新項目，如操作系統的詳細信息、安裝的應用程序列表、庫等等。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Cube-Startup-Create-or-choose-a-project-to-be-managed_0013.png" alt=""></p><p>如您所知，我們的系統是離線的，意思是沒有網絡連接。所以我點擊<strong>取消</strong>按紐來跳過資源庫的更新過程。隨後我們會在一台有網絡連接的系統上更新此資源庫。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Camicri-Systems-%C2%A9-Cube-Portable-Package-Manager-1.0.9.2-sk_0023.png" alt=""></p><p>再一次，在這台離線機器上我們點擊 <strong>No</strong> 來跳過更新，因為我們沒有網絡連接。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Camicri-Systems-%C2%A9-Cube-Portable-Package-Manager-1.0.9.2-sk_0033.png" alt=""></p><p>就是這樣。現在新的項目已經創建好了，它會保存在我們的主 cube 目錄裏面。進入 Cube 目錄，您就會發現一個名叫 Projects 的目錄。這個目錄會保存有您的離線系統的必要完整詳細信息。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Selection_004.png" alt=""></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Selection_005.png" alt=""></p><p>現在，關閉 cube 應用程序，然後拷貝整個主 <strong>cube</strong> 文件夾到任何的閃存盤裏，接入有網絡連接的系統。</p><h4 id="在線系統上操作步驟" tabindex="-1">在線系統上操作步驟: <a class="header-anchor" href="#在線系統上操作步驟" aria-label="Permalink to “在線系統上操作步驟:”">​</a></h4><p>往下的操作步驟需要在有網絡連接的系統上進行。在我們的例子中，用的是 <strong>Lubuntu 14.04</strong> 系統的機器。</p><p>跟在源機器上的操作一樣設置使 cube 目錄具有可執行權限。</p><pre><code>sudo chmod -R +x cube/
</code></pre><p>現在，雙擊 cube-linux 文件運行應用程序或者也可以在終端上加載運行，如下所示：</p><pre><code>cd cube/
./cube-linux
</code></pre><p>在窗口的 “Open Existing Projects” 部分會看到您的項目列表，選擇您需要的項目。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Cube-Startup-Create-or-choose-a-project-to-be-managed_0014.png" alt=""></p><p>隨後，cube 會詢問這是否是您的項目所在的源機器。它並不是我的源（離線）機器，所以我點擊 <strong>No</strong>。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Camicri-Systems-%C2%A9-Cube-Portable-Package-Manager-1.0.9.2-sk_0024.png" alt=""></p><p>接着會詢問是否想要更新您的資源庫。點擊 <strong>OK</strong> 來更新資料庫。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Camicri-Systems-%C2%A9-Cube-Portable-Package-Manager-1.0.9.2-sk_0034.png" alt=""></p><p>下一步，我們得更新所有過期的包/應用程序。點擊 Cube 工具欄上的 “<strong>Mark All updates</strong>” 按紐。然後點擊 “<strong>Download all marked</strong>” 按紐來更新所有過期的包/應用程序。如下截圖所示，在我的例子當中，有302個包需要更新。這時，點擊 <strong>OK</strong> 來繼續下載所標記的安裝包。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Camicri-Systems-%C2%A9-Cube-Portable-Package-Manager-1.0.9.2-sk_005.png" alt=""></p><p>現在，Cube 會開始下載所有已標記的包。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Downloading-packages_006.png" alt=""></p><p>我們已經完成了對資料庫和安裝包的更新。此時，如果您在離線系統上還需要其它的安裝包，您也可以下載這些新的安裝包。</p><h4 id="下載新的應用程序" tabindex="-1">下載新的應用程序 <a class="header-anchor" href="#下載新的應用程序" aria-label="Permalink to “下載新的應用程序”">​</a></h4><p>例如，現在我想下載 <strong>apache2</strong> 包。在<strong>搜索</strong>框裏輸入包的名字，點擊搜索按紐。Cube 程序會獲取您想查找的應用程序的詳細信息。點擊 “<strong>Download this package now</strong>”按紐，接着點擊 <strong>OK</strong> 就開始下載了。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Camicri-Systems-%C2%A9-Cube-Portable-Package-Manager-1.0.9.2-sk_008.png" alt=""></p><p>Cube 將會下載 apache2 的安裝包及所有的依賴包。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Downloading-packages_009.png" alt=""></p><p>如果您想查找和下載更多安裝包的話，只要簡單的點擊 “<strong>Mark this package</strong>” 按紐就可以搜索到需要的包了。只要您想在源機器上安裝的包都可以標記上。一旦標記完所有的包，就可以點擊位於頂部工具欄的 “<strong>Download all marked</strong>” 按紐來下載它們。</p><p>在完成資源庫、過期軟件包的更新和下載好新的應用程序後，就可以關閉 Cube 應用程序。然後，拷貝整個 Cube 文件夾到任何的閃盤或者外接硬盤。回到您的離線系統中來。</p><h4 id="離線機器上的操作步驟" tabindex="-1">離線機器上的操作步驟: <a class="header-anchor" href="#離線機器上的操作步驟" aria-label="Permalink to “離線機器上的操作步驟:”">​</a></h4><p>把 Cube 文件夾拷回您的離線系統的任意位置。進入 cube 目錄，並且雙擊 <strong>cube-linux</strong> 文件來加載啓動 Cube 應用程序。</p><p>或者，您也可以從終端下啓動它，如下所示：</p><pre><code>cd cube/
./cube-linux
</code></pre><p>選擇您的項目，點擊打開。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Cube-Startup-Create-or-choose-a-project-to-be-managed_0012.png" alt=""></p><p>然後會彈出一個對話框詢問是否更新系統，尤其是已經下載好新的資源庫的時候，請點擊“是”。因為它會把所有的資源庫傳輸到您的機器上。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Camicri-Systems-%C2%A9-Cube-Portable-Package-Manager-1.0.9.2-sk_0021.png" alt=""></p><p>您會看到，在沒有網絡連接的情況下這些資源庫會更新到您的離線機器上。那是因為我們已經在有網絡連接的系統上下載更新了此資源庫。看起來很酷，不是嗎？</p><p>更新完資源庫後，讓我們來安裝所有的下載包。點擊 “Mark all Downloaded” 按紐選中所有的下載包，然後點擊 Cube 工具欄上的 “Install All Marked” 按紐來安裝它們。Cube 應用程序會自動打開一個新的終端窗口來安裝所有的軟件包。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Terminal_001.png" alt=""></p><p>如果遇到依賴的問題，進入 <strong>Cube Menu -&gt; Packages -&gt; Install packages with complete dependencies</strong> 來安裝所有的依賴包。</p><p>如果您只想安裝特定的包，定位到列表包位置，點擊 “Downloaded” 按紐，所有的已下載包都會被列出來。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Camicri-Systems-%C2%A9-Cube-Portable-Package-Manager-1.0.9.2-sk_0035.png" alt=""></p><p>然後雙擊某個特定的包，點擊 “Install this”按紐來安裝或者如果想過後再安裝它的話可以先點擊 “Mark this” 按紐。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/07/Camicri-Systems-%C2%A9-Cube-Portable-Package-Manager-1.0.9.2-sk_0043.png" alt=""></p><p>順便提一句，您可以在任意已經連接網絡的系統上下載所需要的包，然後在沒有網絡連接的離線系統上安裝。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>這是我曾經使用過的最好、最有用的軟件工具之一。但我在用 Ubuntu 14.04 測試盒子測試的時候，遇到了很多依賴問題，還經常會出現閃退的情況。也僅僅是在最新 Ubuntu 14.04 離線系統上使用沒有遇到任何問題。希望這些問題在老版本的 Ubuntu 上不會發生。除了這些小問題，這個小工具就如同宣傳的一樣，像魔法一樣神奇。</p><p>歡呼吧!</p><p>原文作者：</p><p><img src="http://1.gravatar.com/avatar/1ba62ac2b395f541750b6b4f873eb37b?s=70&amp;d=monsterid&amp;r=G" alt=""></p>`,69)),r("p",null,[n(a,{href:"http://www.unixmen.com/author/sk/"},{default:p(()=>[...e[5]||(e[5]=[t("SK",-1)])]),_:1}),e[6]||(e[6]=t("(Senthilkumar，又名SK，來自於印度的泰米爾納德邦，Linux 愛好者，FOSS 論壇支持者和 Linux 板塊顧問。一個充滿激情和活力的人，致力於提供高質量的 IT 專業文章，非常喜歡寫作以及探索 Linux、開源、電腦和互聯網等新事物。)",-1))]),e[20]||(e[20]=r("hr",null,null,-1)),r("p",null,[e[8]||(e[8]=t("via: ",-1)),n(a,{href:"http://www.unixmen.com/camicri-cube-offline-portable-package-management-system/"},{default:p(()=>[...e[7]||(e[7]=[t("http://www.unixmen.com/camicri-cube-offline-portable-package-management-system/",-1)])]),_:1})]),r("p",null,[e[11]||(e[11]=t("譯者：",-1)),n(a,{href:"https://github.com/runningwater"},{default:p(()=>[...e[9]||(e[9]=[t("runningwater",-1)])]),_:1}),e[12]||(e[12]=t(" 校對：",-1)),n(a,{href:"https://github.com/carolinewuyan"},{default:p(()=>[...e[10]||(e[10]=[t("Caroline",-1)])]),_:1})]),r("p",null,[e[15]||(e[15]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原創翻譯，",-1)),n(a,{href:"http://linux.cn/"},{default:p(()=>[...e[14]||(e[14]=[t("Linux中國",-1)])]),_:1}),e[17]||(e[17]=t(" 榮譽推出",-1))])])}const w=s(c,[["render",g]]);export{P as __pageData,w as default};
